using System;using System.IO;using System.IO.Compression;using System.Text;using System.Collections.Generic;using System.Drawing;using System.Windows.Forms;using EanEtikety;
using System.Linq;using System.Net;using System.Net.Http;using System.Threading;using System.Threading.Tasks;
class UpdateTests {
 static int checks;static string root;static void Check(bool b,string m){checks++;if(!b)throw new Exception(m);}
 static void Reject(Action a,string name){bool failed=false;try{a();}catch{failed=true;}Check(failed,name);}
 static string Fixture(string name,string family,out UpdatePackage package){string path=Path.Combine(root,name+".zip");package=new UpdatePackage{Family=family,SourceCommit=new string('a',40)};var files=new[]{"ND-LabelDesigner.exe","ND-LabelDesigner.dll","ND-LabelDesigner.runtimeconfig.json","LabelDesigner.Core.dll","zxing.dll","coreclr.dll","hostfxr.dll","System.Private.CoreLib.dll"};using(var zip=ZipFile.Open(path,ZipArchiveMode.Create)){foreach(var file in files){var bytes=Encoding.UTF8.GetBytes(name+" fixture "+file);using(var s=zip.CreateEntry(file).Open())s.Write(bytes,0,bytes.Length);package.Files.Add(new UpdateFile{Path=file,Size=bytes.Length,Sha256=UpdateFiles.Digest(bytes)});}package.PackageId=package.ComputeId();var xml=Encoding.UTF8.GetBytes(ProjectXml.Encode(package));using(var s=zip.CreateEntry("package-manifest.xml").Open())s.Write(xml,0,xml.Length);}return path;}
 static void Packages(){UpdatePackage p;string zip=Fixture("good",UpdateFiles.CurrentFamily,out p),managed=Path.Combine(root,"managed");string installed=UpdatePreparation.Prepare(zip,UpdateFiles.Hash(zip),p.Family,managed);Check(Directory.Exists(installed),"verified package promoted");p.VerifyDirectory(installed);Check(UpdatePreparation.Prepare(zip,UpdateFiles.Hash(zip),p.Family,managed)==installed,"repeat preparation validates existing package");
  Reject(()=>UpdatePreparation.Prepare(zip,new string('0',64),p.Family,managed),"wrong ZIP hash rejected");Reject(()=>UpdatePreparation.Prepare(zip,UpdateFiles.Hash(zip),"framework",managed),"wrong family rejected");
  foreach(string bad in new[]{"../escape","/absolute","C:/escape","x\\escape","a:stream","CON.txt","a/../b","a//b","trailing. ","dir./x"})Reject(()=>UpdateFiles.SafeName(bad),"unsafe path "+bad);
  var badManifest=ProjectXml.Decode<UpdatePackage>(ProjectXml.Encode(p));badManifest.Files.Add(new UpdateFile{Path=p.Files[0].Path.ToUpperInvariant(),Size=1,Sha256=new string('0',64)});badManifest.PackageId=badManifest.ComputeId();Reject(badManifest.Validate,"case duplicate rejected");badManifest=ProjectXml.Decode<UpdatePackage>(ProjectXml.Encode(p));badManifest.Files[0].Size=129L*1024*1024;badManifest.PackageId=badManifest.ComputeId();Reject(badManifest.Validate,"expanded file cap");
  string tampered=Path.Combine(root,"tampered.zip");File.Copy(zip,tampered);using(var z=ZipFile.Open(tampered,ZipArchiveMode.Update)){var e=z.GetEntry(p.Files[0].Path);e.Delete();using(var s=z.CreateEntry(p.Files[0].Path).Open()){var bytes=new byte[p.Files[0].Size];s.Write(bytes,0,bytes.Length);}}Reject(()=>UpdatePreparation.Prepare(tampered,UpdateFiles.Hash(tampered),p.Family,Path.Combine(root,"bad-managed")),"inner file corruption rejected even when ZIP hash matches");
  using(var c=new WorkContextForTest()){var context=new WorkContext(progress=>c.Context.Cancel());c.Context=context;using(context.Enter())Reject(()=>UpdatePreparation.Prepare(zip,UpdateFiles.Hash(zip),p.Family,Path.Combine(root,"cancelled")),"cancel preparation");}Check(Directory.GetDirectories(Path.Combine(root,"cancelled"),".pending-*").Length==0,"cancel removes only owned staging");
  string linked=Path.Combine(root,"linked.zip");File.Copy(zip,linked);using(var z=ZipFile.Open(linked,ZipArchiveMode.Update))z.GetEntry(p.Files[0].Path).ExternalAttributes=unchecked((int)0xA1FF0000);Reject(()=>UpdatePreparation.Prepare(linked,UpdateFiles.Hash(linked),p.Family,Path.Combine(root,"link-managed")),"linked archive entry rejected");string sums=Path.Combine(root,"SHA256SUMS.txt");File.WriteAllText(sums,UpdateFiles.Hash(zip)+"  "+Path.GetFileName(zip));Check(UpdatePreparation.ReadChecksum(sums,Path.GetFileName(zip))==UpdateFiles.Hash(zip),"offline checksum selection");Reject(()=>UpdatePreparation.ReadChecksum(sums,"other.zip"),"wrong checksum filename");
 }
 sealed class WorkContextForTest:IDisposable{public WorkContext Context;public void Dispose(){}}
 sealed class FakeHttp:HttpMessageHandler{public int Requests;public Func<HttpRequestMessage,HttpResponseMessage> Reply;protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken token){Requests++;try{return Task.FromResult(Reply(request));}catch(Exception ex){var t=new TaskCompletionSource<HttpResponseMessage>();t.SetException(ex);return t.Task;}}}
 sealed class PendingHttp:HttpMessageHandler{protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken token){var t=new TaskCompletionSource<HttpResponseMessage>();token.Register(()=>t.TrySetCanceled());return t.Task;}}
 sealed class CancelStream:MemoryStream{readonly Action cancel;public CancelStream(byte[] data,Action cancel):base(data){this.cancel=cancel;}public override Task<int> ReadAsync(byte[] buffer,int offset,int count,CancellationToken token){int read=Read(buffer,offset,Math.Min(10,count));cancel();return Task.FromResult(read);}}
 static HttpResponseMessage Response(byte[] bytes){return new HttpResponseMessage(HttpStatusCode.OK){Content=new ByteArrayContent(bytes)};}
 static void Network(){UpdatePackage p;string zip=Fixture("network",UpdateFiles.CurrentFamily,out p);var bytes=File.ReadAllBytes(zip);var offer=new UpdateOffer{Family=p.Family,SourceCommit=p.SourceCommit,PackageId=p.PackageId,Sha256=UpdateFiles.Hash(zip),AssetName=UpdateFiles.AssetName(p.Family),Size=bytes.Length};var index=new UpdateIndex{SourceCommit=p.SourceCommit};index.Packages.Add(offer);var xml=Encoding.UTF8.GetBytes(ProjectXml.Encode(index));
  index.Validate();
  index.Packages.Clear();Reject(index.Validate,"index requires one offer");
  index.Packages.Add(offer);index.Packages.Add(offer);Reject(index.Validate,"index rejects extra offers");
  index.Packages.RemoveAt(1);
  offer.Family="framework";Reject(index.Validate,"retired Framework offer rejected");offer.Family=p.Family;
  string json="{\"id\":1,\"tag_name\":\"Pre-release\",\"target_commitish\":\""+p.SourceCommit+"\",\"draft\":false,\"prerelease\":true,\"assets\":[{\"id\":2,\"name\":\"UPDATE-INDEX.xml\",\"size\":"+xml.Length+",\"digest\":\"sha256:"+UpdateFiles.Digest(xml)+"\"},{\"id\":3,\"name\":\""+offer.AssetName+"\",\"size\":"+bytes.Length+",\"digest\":\"sha256:"+offer.Sha256+"\"}]}";
  var handler=new FakeHttp{Reply=request=>Response(request.RequestUri.AbsolutePath.EndsWith("/2")?xml:request.RequestUri.AbsolutePath.EndsWith("/3")?bytes:Encoding.UTF8.GetBytes(json))};using(var client=new UpdateNetwork(handler)){Check(handler.Requests==0,"constructing updater never contacts network");var found=client.Check(p.Family);Check(found.PackageId==p.PackageId&&found.AssetId==3,"online check pins release/index/asset identity");string downloaded=client.Download(found,Path.Combine(root,"downloads"));Check(UpdateFiles.Hash(downloaded)==offer.Sha256,"streamed download verified");handler.Reply=request=>Response(new byte[]{0});Reject(()=>client.Download(found,Path.Combine(root,"bad-download")),"truncated download rejected");Check(Directory.GetFiles(Path.Combine(root,"bad-download")).Length==0,"failed download leaves no completed ZIP");}
  foreach(string url in new[]{"http://github.com/a","https://evil.example/a","https://github.com:444/a","https://user@github.com/a","https://127.0.0.1/a"})Check(!UpdateNetwork.AllowedUrl(new Uri(url)),"reject network target "+url);
  var redirect=new FakeHttp{Reply=request=>{var r=new HttpResponseMessage(HttpStatusCode.Redirect);r.Headers.Location=new Uri("http://evil.example/a");return r;}};using(var client=new UpdateNetwork(redirect)){Reject(()=>client.Check(p.Family),"unsafe redirect rejected");Check(redirect.Requests==1,"unsafe redirect never requested");}
  using(var client=new UpdateNetwork(new FakeHttp{Reply=request=>{throw new HttpRequestException("offline");}}))Reject(()=>client.Check(p.Family),"offline failure handled without activation");
  var cancelled=new WorkContext();cancelled.Cancel();var untouched=new FakeHttp{Reply=request=>Response(bytes)};using(cancelled.Enter())using(var client=new UpdateNetwork(untouched))Reject(()=>client.Check(p.Family),"cancel before HTTP");Check(untouched.Requests==0,"cancelled action makes no request");
  using(var client=new UpdateNetwork(new PendingHttp())){typeof(UpdateNetwork).GetField("timeoutMilliseconds",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).SetValue(client,40);Reject(()=>client.Check(p.Family),"stalled connection times out");}
  var during=new WorkContext();var streamHandler=new FakeHttp{Reply=request=>new HttpResponseMessage(HttpStatusCode.OK){Content=new StreamContent(new CancelStream(bytes,()=>during.Cancel()))}};offer.AssetId=3;using(during.Enter())using(var client=new UpdateNetwork(streamHandler))Reject(()=>client.Download(offer,Path.Combine(root,"cancel-download")),"cancel during download");Check(Directory.GetFiles(Path.Combine(root,"cancel-download")).Length==0,"cancelled download cleaned atomically");
 }
 static void Activation(){UpdatePackage old,next;string oldZip=Fixture("old",UpdateFiles.CurrentFamily,out old),newZip=Fixture("next",UpdateFiles.CurrentFamily,out next);string oldRoot=UpdatePreparation.Prepare(oldZip,UpdateFiles.Hash(oldZip),old.Family,Path.Combine(root,"old-root"));string prefs=Path.Combine(root,"data","startup.xml");Directory.CreateDirectory(Path.GetDirectoryName(prefs));File.WriteAllText(prefs,"preferences");Directory.CreateDirectory(prefs+".workspace");File.WriteAllText(Path.Combine(prefs+".workspace","printers.xml"),"media calibration");var service=new UpdateActivation(Path.Combine(root,"activation"),old.Family,prefs);string fresh=UpdatePreparation.Prepare(newZip,UpdateFiles.Hash(newZip),next.Family,service.PackagesRoot);string injected=Path.Combine(fresh,"undeclared.dll");File.WriteAllText(injected,"injected");Reject(()=>service.Activate(oldRoot,fresh,exe=>true),"undeclared code cannot activate");File.Delete(injected);File.WriteAllText(Path.Combine(oldRoot,"project.ean.xml"),"user project");int launches=0;service.Activate(oldRoot,fresh,exe=>{launches++;return true;});Check(launches==1&&service.State().Current.PackageId==next.PackageId,"activation only launches selected verified package");Check(File.ReadAllText(prefs)=="preferences"&&File.ReadAllText(Path.Combine(prefs+".workspace","printers.xml"))=="media calibration","activation preserves settings and profiles");Check(File.Exists(Path.Combine(service.State().BackupDirectory,"workspace","printers.xml")),"settings backed up before activation");Check(service.RedirectTarget(oldRoot)==Path.Combine(fresh,"ND-LabelDesigner.exe")&&service.RedirectTarget(fresh)==null,"local authorized startup redirection");Check(service.RedirectTarget(root)==null,"unrelated install never redirected");service.Rollback(fresh,exe=>true);Check(service.State().Current.PackageId==old.PackageId&&service.RedirectTarget(fresh)==Path.Combine(oldRoot,"ND-LabelDesigner.exe"),"confirmed rollback retains and selects old package");Reject(()=>service.Activate(oldRoot,fresh,exe=>false),"launch failure rejected");Check(service.State().Current.PackageId==old.PackageId,"launch failure restores previous activation state");File.WriteAllText(service.StatePath,"corrupt");Check(service.State().Current.PackageId==old.PackageId,"failed launch cannot poison fallback state");Check(Directory.Exists(oldRoot)&&Directory.Exists(fresh),"both complete installations retained");using(var locked=new FileStream(prefs,FileMode.Open,FileAccess.Read,FileShare.None))Reject(()=>service.Activate(oldRoot,fresh,exe=>true),"locked settings abort activation before state change");Check(service.State().Current.PackageId==old.PackageId,"failed settings backup preserves activation");using(var locked=new FileStream(Path.Combine(oldRoot,"ND-LabelDesigner.exe"),FileMode.Open,FileAccess.Read,FileShare.Read)){UpdatePackage lockedPackage;string lockedZip=Fixture("locked-current",old.Family,out lockedPackage);Check(Directory.Exists(UpdatePreparation.Prepare(lockedZip,UpdateFiles.Hash(lockedZip),lockedPackage.Family,service.PackagesRoot)),"locked current executable is not replaced during preparation");}var bounded=service.State();for(int i=bounded.AuthorizedRoots.Count;i<64;i++)bounded.AuthorizedRoots.Add(Path.Combine(root,"historical-"+i));ProjectXml.Save(service.StatePath,bounded);UpdatePackage third;string thirdZip=Fixture("limit-next",old.Family,out third);string thirdRoot=UpdatePreparation.Prepare(thirdZip,UpdateFiles.Hash(thirdZip),third.Family,service.PackagesRoot);service.Activate(oldRoot,thirdRoot,exe=>true);Check(service.State().AuthorizedRoots.Count<=64&&service.State().Current.PackageId==third.PackageId,"history at capacity still permits updates");service.Rollback(thirdRoot,exe=>true);File.WriteAllText(Path.Combine(fresh,next.Files[0].Path),"corrupt");Reject(()=>service.Activate(oldRoot,fresh,exe=>true),"corrupt staged install cannot activate");Check(service.State().Current.PackageId==old.PackageId,"bad package leaves activation unchanged");}
 static void Cleanup(){
  var service=new UpdateActivation(Path.Combine(root,"cleanup"),UpdateFiles.CurrentFamily,Path.Combine(root,"cleanup-data","startup.xml"));
  string Install(string name,string store){var zip=Fixture(name,service.Family,out var package);return UpdatePreparation.Prepare(zip,UpdateFiles.Hash(zip),package.Family,store);}
  string anchor=Install("cleanup-anchor",Path.Combine(root,"cleanup-anchor"));
  string oldest=Install("cleanup-first",service.PackagesRoot);
  string backupOnly=Install("cleanup-backup",service.PackagesRoot);
  string rollback=Install("cleanup-rollback",service.PackagesRoot);
  string current=Install("cleanup-current",service.PackagesRoot);
  service.Activate(anchor,oldest,_=>true);
  service.Activate(oldest,backupOnly,_=>true);
  service.Activate(backupOnly,rollback,_=>true);
  Check(Directory.Exists(oldest),"backup state still references the oldest installed package");
  Reject(()=>service.Activate(rollback,current,_=>false),"failed activation does not run cleanup");
  Check(Directory.Exists(oldest),"failed activation leaves normally reclaimable package intact");
  service.Activate(rollback,current,_=>true);
  Check(!Directory.Exists(oldest),"successful switch reclaims obsolete verified managed package");
  Check(Directory.Exists(backupOnly)&&Directory.Exists(rollback)&&Directory.Exists(current),"cleanup retains current, rollback and fallback references");
  Check(service.RedirectTarget(anchor)==Path.Combine(current,"ND-LabelDesigner.exe"),"cleanup preserves manually extracted shortcut anchor");

  string prepared=Install("cleanup-prepared",service.PackagesRoot);
  string running=Install("cleanup-running",service.PackagesRoot);
  string unchanged=Install("cleanup-removable",service.PackagesRoot);
  string changed=Install("cleanup-changed",service.PackagesRoot);
  string malformed=Install("cleanup-malformed",service.PackagesRoot);
  string unknown=Install("cleanup-unknown",service.PackagesRoot);
  string locked=Install("cleanup-locked",service.PackagesRoot);
  string project=Path.Combine(changed,"custom.ean.xml");
  File.WriteAllText(project,"user data");
  File.WriteAllText(Path.Combine(malformed,"package-manifest.xml"),"<");
  var state=service.State();state.AuthorizedRoots.AddRange(new[]{prepared,running,malformed,unchanged,changed,locked});
  ProjectXml.Save(service.StatePath,state);
  long bytes=new DirectoryInfo(unchanged).GetFiles().Sum(f=>f.Length);
  using(var handle=new FileStream(Path.Combine(locked,"ND-LabelDesigner.exe"),FileMode.Open,FileAccess.Read,FileShare.None)){
   var result=service.Cleanup(running,prepared);
   Check(result.Count==1&&result.Bytes==bytes&&!Directory.Exists(unchanged),"manual cleanup reports files actually removed");
  }
  Check(Directory.Exists(prepared)&&Directory.Exists(running)&&Directory.Exists(locked),"cleanup skips prepared, running and locked packages");
  Check(File.ReadAllText(project)=="user data"&&Directory.Exists(malformed)&&Directory.Exists(unknown)&&Directory.Exists(anchor),"cleanup skips modified, malformed, unrecorded and external folders");
  Check(service.State().Current.Directory==current&&service.State().Previous.Directory==rollback,"cleanup preserves activation state");
  service.Rollback(current,_=>true);
  Check(service.RedirectTarget(anchor)==Path.Combine(rollback,"ND-LabelDesigner.exe"),"rollback still works through original anchor after cleanup");
 }
 static readonly System.Reflection.BindingFlags Hidden=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic;
 static void Set(object o,string name,object value){o.GetType().GetField(name,Hidden).SetValue(o,value);}static object Call(object o,string name,params object[] args){return o.GetType().GetMethod(name,Hidden).Invoke(o,args);}
 static void Ui(){UpdatePackage a,b;string az=Fixture("ui-old",UpdateFiles.CurrentFamily,out a),bz=Fixture("ui-next",UpdateFiles.CurrentFamily,out b);string original=UpdatePreparation.Prepare(az,UpdateFiles.Hash(az),a.Family,Path.Combine(root,"ui-original"));string prefs=Path.Combine(root,"ui-prefs.xml");var service=new UpdateActivation(Path.Combine(root,"ui-store"),a.Family,prefs);string next=UpdatePreparation.Prepare(bz,UpdateFiles.Hash(bz),b.Family,service.PackagesRoot);int requests=0;
  using(var dialog=new UpdatesDialog(service,original,null)){Set(dialog,"networkFactory",(Func<UpdateNetwork>)(()=>{requests++;throw new Exception("network must require click");}));Check(requests==0,"update UI constructor does not contact network");Check(!dialog.PrepareLocal(bz,"none",false),"untrusted local import never starts");Call(dialog,"Ready",next);Set(dialog,"confirm",(Func<string,bool>)(message=>false));Call(dialog,"RequestActivation");Check(dialog.RequestedDirectory==null&&service.State().Current==null,"declined restart never activates");Set(dialog,"confirm",(Func<string,bool>)(message=>true));Call(dialog,"RequestActivation");Check(dialog.RequestedDirectory==next&&service.State().Current==null,"accepted dialog requests switch but cannot bypass document-close gate");}
  foreach(string language in Loc.Codes){Loc.Language=language;using(var view=new UpdatesDialog(service,original,null)){view.StartPosition=FormStartPosition.Manual;view.Location=new Point(-20000,-20000);view.Show();view.ClientSize=new Size(520,400);Application.DoEvents();var button=(Button)view.GetType().GetField("activate",Hidden).GetValue(view);var scroll=(Panel)view.Controls[0];scroll.ScrollControlIntoView(button);Application.DoEvents();var bounds=scroll.RectangleToClient(button.RectangleToScreen(button.ClientRectangle));Check(bounds.Top>=0&&bounds.Bottom<=scroll.ClientSize.Height,"activation reachable in minimum dialog "+language);Check(language=="sk"||Loc.T("Skontrolovať aktualizácie")!="Skontrolovať aktualizácie","update menu translated "+language);if(language=="sk"){using(var image=new Bitmap(view.Width,view.Height)){view.DrawToBitmap(image,new Rectangle(0,0,image.Width,image.Height));image.Save(Path.Combine(root,"updates-dialog.png"));}}view.Close();}}Loc.Language="sk";using(var form=new MainForm(prefs)){form.StartPosition=FormStartPosition.Manual;form.Location=new Point(-20000,-20000);form.Show();Application.DoEvents();Set(form,"updateRunningDirectory",original);int launches=0;Set(form,"updateLauncher",(Func<string,bool>)(exe=>{launches++;return true;}));Set(form,"dirty",true);bool asked=false;using(var timer=new System.Windows.Forms.Timer{Interval=20}){timer.Tick+=delegate{var forms=new List<Form>();foreach(Form open in Application.OpenForms)forms.Add(open);foreach(var open in forms)if(open!=form&&open.Text==Loc.T("Neuložené nastavenie")){asked=true;open.DialogResult=DialogResult.Cancel;open.Close();timer.Stop();break;}};timer.Start();Call(form,"CompleteUpdateSwitch",service,next,false);timer.Stop();}Check(asked&&!form.IsDisposed&&launches==0&&service.State().Current==null,"unsaved-document cancellation preserves running editor and activation state");Set(form,"dirty",false);form.Close();}
 }
 [STAThread]static void Main(string[] args){root=args[0];Directory.CreateDirectory(root);try{Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Packages();Network();Activation();Cleanup();Ui();File.WriteAllText(Path.Combine(root,"passed.txt"),"PASS "+checks+" update integrity, network, activation, rollback and consent checks; no production update launched");}catch(Exception ex){File.WriteAllText(Path.Combine(root,"failed.txt"),ex.ToString());Environment.ExitCode=1;}}
